SELECT json_object('obs','text','declined',CASE WHEN (SELECT text FROM blocks WHERE doc_id=1 AND unit='page' AND ordering=1) IS NULL THEN 1 ELSE 0 END,'value_kind','text','value',(SELECT text FROM blocks WHERE doc_id=1 AND unit='page' AND ordering=1),'coord',json_object('format',(SELECT format FROM documents WHERE doc_id=1),'kind','page','ordinal',1),'provenance',json_object('class',(SELECT class FROM provenance WHERE block_id=(SELECT block_id FROM blocks WHERE doc_id=1 AND unit='page' AND ordering=1)),'span',(SELECT CASE WHEN span_start IS NULL THEN NULL ELSE json_array(span_start,span_end) END FROM provenance WHERE block_id=(SELECT block_id FROM blocks WHERE doc_id=1 AND unit='page' AND ordering=1))),'exact',json_object('length',(SELECT source_len FROM documents WHERE doc_id=1),'sha256',(SELECT source_sha256 FROM documents WHERE doc_id=1)),'revision',NULL)